import { createHmac, timingSafeEqual } from "node:crypto";
import type { Request } from "express";
import { ENV } from "./_core/env";

/** Server-side test tooling only. This token is never generated by the browser. */
export function createIntakeTestAuthorization(submissionId: string, now = Date.now()): string {
  if (!ENV.cookieSecret) throw new Error("Intake test authorization is unavailable.");
  const payload = Buffer.from(JSON.stringify({ purpose: "mmd-normal-intake-test-v1", submission_id: submissionId, expires_at: now + 5 * 60_000 })).toString("base64url");
  return `${payload}.${createHmac("sha256", ENV.cookieSecret).update(payload).digest("base64url")}`;
}

/** Classifies an authorized synthetic normal-flow submission; grants no clinical/phone bypass. */
export function authorizedNormalIntakeTest(req: Request, submissionId: string, requested: boolean, now = Date.now()): boolean {
  if (!requested || !ENV.cookieSecret) return false;
  const value = req.headers?.["x-mmd-intake-test"];
  if (typeof value !== "string" || value.length > 2048) return false;
  try {
    const parts = value.split(".");
    if (parts.length !== 2) return false;
    const [body, supplied] = parts;
    const expected = createHmac("sha256", ENV.cookieSecret).update(body).digest("base64url");
    if (supplied.length !== expected.length || !timingSafeEqual(Buffer.from(supplied), Buffer.from(expected))) return false;
    const token = JSON.parse(Buffer.from(body, "base64url").toString("utf8"));
    return token.purpose === "mmd-normal-intake-test-v1" && token.submission_id === submissionId && Number.isSafeInteger(token.expires_at) && token.expires_at > now && token.expires_at <= now + 5 * 60_000;
  } catch { return false; }
}
